const canvas=document.querySelector('#orbit'),ctx=canvas.getContext('2d');
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
let width=0,height=0,angle=.3,tilt=.55,paused=reduced.matches,drag=false,lastX=0,lastY=0,frame=0;
const points=[];for(let i=0;i<105;i++){const u=i/105*Math.PI*2;for(let j=0;j<42;j++){const v=j/42*Math.PI*2;const r=1.28+.46*Math.cos(v);points.push([r*Math.cos(u),r*Math.sin(u),.46*Math.sin(v),u,v]);}}
function resize(){const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);render();}
function render(){ctx.clearRect(0,0,width,height);const scale=Math.min(width,height)*.24;const data=points.map(([x,y,z,u,v])=>{let ax=x*Math.cos(angle)-z*Math.sin(angle),az=x*Math.sin(angle)+z*Math.cos(angle);let ay=y*Math.cos(tilt)-az*Math.sin(tilt),bz=y*Math.sin(tilt)+az*Math.cos(tilt);const rz=-.55;return{x:ax*Math.cos(rz)-ay*Math.sin(rz),y:ax*Math.sin(rz)+ay*Math.cos(rz),z:bz,u,v};}).sort((a,b)=>a.z-b.z);const glow=ctx.createRadialGradient(width*.5,height*.52,0,width*.5,height*.52,scale*2);glow.addColorStop(0,'#9bca5520');glow.addColorStop(1,'#9bca5500');ctx.fillStyle=glow;ctx.fillRect(0,0,width,height);for(const p of data){const perspective=4.7/(4.7-p.z);const light=(p.z+1.75)/3.5;ctx.fillStyle=`rgba(${Math.round(130+light*100)},${Math.round(156+light*96)},${Math.round(86+light*72)},${.22+light*.74})`;ctx.beginPath();ctx.arc(width*.5+p.x*scale*perspective,height*.5+p.y*scale*perspective,(.65+light*.95)*perspective,0,Math.PI*2);ctx.fill();}}
let previous=0;function animate(time){if(time-previous>30){if(!paused&&!drag){angle+=.006;render();}previous=time;}frame=requestAnimationFrame(animate);}new ResizeObserver(resize).observe(canvas);frame=requestAnimationFrame(animate);
canvas.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;angle+=(e.clientX-lastX)*.01;tilt+=(e.clientY-lastY)*.008;lastX=e.clientX;lastY=e.clientY;render();});for(const event of ['pointerup','pointercancel'])canvas.addEventListener(event,()=>drag=false);
const motion=document.querySelector('#motion');function syncMotion(){motion.textContent=paused?'▶':'Ⅱ';motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'เปิดการเคลื่อนไหว':'หยุดการเคลื่อนไหว');}syncMotion();motion.addEventListener('click',()=>{paused=!paused;syncMotion();});reduced.addEventListener('change',e=>{paused=e.matches;syncMotion();});
const projects={farm:{title:'Smart Farm',description:'โปรเจ็กต์ด้านการเกษตรอัจฉริยะ สำรวจการนำเทคโนโลยีและการพัฒนา Full-stack มาใช้กับงานเกษตร',area:'Smart Farm / Full-stack Development'},canteen:{title:'Canteen Space Detection',description:'โปรเจ็กต์ Machine Learning สำหรับตรวจสอบพื้นที่ว่างในโรงอาหาร โดยชื่อและคำอธิบายนี้ตีความจาก “check emty carteen” และสามารถปรับให้ตรงกับขอบเขตโปรเจ็กต์จริงได้',area:'Machine Learning / Space Detection'}};
const dialog=document.querySelector('#project-dialog');document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects[button.dataset.project];document.querySelector('#dialog-title').textContent=p.title;document.querySelector('#dialog-description').textContent=p.description;document.querySelector('#dialog-area').textContent=p.area;dialog.showModal();}));dialog.setAttribute('aria-labelledby','dialog-title');document.querySelectorAll('.close,.close-bottom').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
document.querySelector('#copy-name').addEventListener('click',async()=>{const status=document.querySelector('#status');try{await navigator.clipboard.writeText('Punjapol Inthaprasart');status.textContent='คัดลอกชื่อ Punjapol Inthaprasart แล้ว';}catch{status.textContent='ชื่อสำหรับคัดลอก: Punjapol Inthaprasart';}});
